-- =============================================================================
-- Fame Fleet: complete database (Phase A)
--
--   1. People, vehicles, places, towns, projects
--   2. Tasks, stops, project split, vehicle requests
--   3. Location sharing
--   4. Photos, odometer, fuel, vehicle reports
--   5. Allowance claims (tables only, no access until Phase C)
--   6. Office audit log
--   7. Functions and triggers
--   8. Row Level Security: privileges
--   9. Row Level Security: policies
--  10. Storage bucket "driver-photos" and its policies
--  11. Realtime
--  12. Seed: Sri Lankan towns (GeoNames)
--
-- Who reaches the database
--   * Drivers sign in with Supabase Auth and arrive as role "authenticated".
--     Everything they can do is in sections 8 and 9, and every policy goes
--     through current_employee_id().
--   * The office connector (Edge Function office-mcp) uses service_role, which
--     bypasses RLS. It may read, insert and update, never delete.
--   * anon has no privileges on anything.
--
-- Conventions: times are timestamptz (UTC, shown in Asia/Colombo by the apps);
-- money is LKR in integer cents (bigint); distances are whole km.
-- =============================================================================


-- -----------------------------------------------------------------------------
-- 1. People, vehicles, places, towns, projects
-- -----------------------------------------------------------------------------

create table public.employees (
  id                 uuid primary key default gen_random_uuid(),
  code               text not null,
  name               text not null,
  -- Sign-in name. The Auth email is <username>@drivers.fame.invalid.
  username           text,
  phone              text,
  role               text not null default 'driver',
  active             boolean not null default true,
  language           text not null default 'en',
  licence_expiry     date,
  current_vehicle_id uuid,
  auth_user_id       uuid references auth.users (id) on delete set null,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  constraint employees_code_key unique (code),
  constraint employees_username_key unique (username),
  constraint employees_auth_user_id_key unique (auth_user_id),
  constraint employees_code_not_blank check (btrim(code) <> ''),
  constraint employees_name_not_blank check (btrim(name) <> ''),
  constraint employees_username_format check (username ~ '^[a-z0-9._-]{3,40}$'),
  constraint employees_role_check check (role in ('driver', 'office', 'admin')),
  constraint employees_language_check check (language in ('en', 'si'))
);

create table public.rental_companies (
  id         uuid primary key default gen_random_uuid(),
  name       text not null,
  phone      text,
  created_at timestamptz not null default now(),
  constraint rental_companies_name_not_blank check (btrim(name) <> '')
);

create unique index rental_companies_name_key on public.rental_companies (lower(name));

create table public.vehicles (
  id                       uuid primary key default gen_random_uuid(),
  reg_no                   text not null,
  make_model               text,
  vehicle_type             text not null default 'other',
  seats                    integer,
  rental_company_id        uuid references public.rental_companies (id),
  rent_until               date,
  monthly_rent_cents       bigint,
  monthly_km_allowance     integer,
  regular_driver_id        uuid references public.employees (id),
  current_odometer_km      integer,
  service_interval_km      integer,
  last_service_odometer_km integer,
  next_service_date        date,
  garage_booked_date       date,
  in_garage                boolean not null default false,
  licence_expiry           date,
  insurance_expiry         date,
  emission_expiry          date,
  active                   boolean not null default true,
  created_at               timestamptz not null default now(),
  updated_at               timestamptz not null default now(),
  constraint vehicles_reg_no_key unique (reg_no),
  -- Plates are stored trimmed and in capitals ("WP CAB-4521") so lookups match.
  constraint vehicles_reg_no_format check (reg_no <> '' and reg_no = upper(btrim(reg_no))),
  constraint vehicles_type_check check (vehicle_type in ('car', 'van', 'double_cab', 'lorry', 'other')),
  constraint vehicles_seats_check check (seats > 0),
  constraint vehicles_monthly_rent_check check (monthly_rent_cents >= 0),
  constraint vehicles_monthly_km_allowance_check check (monthly_km_allowance >= 0),
  constraint vehicles_current_odometer_check check (current_odometer_km >= 0),
  constraint vehicles_service_interval_check check (service_interval_km > 0),
  constraint vehicles_last_service_odometer_check check (last_service_odometer_km >= 0)
);

create index vehicles_rental_company_id_idx on public.vehicles (rental_company_id);
create index vehicles_regular_driver_id_idx on public.vehicles (regular_driver_id);

alter table public.employees
  add constraint employees_current_vehicle_id_fkey
  foreign key (current_vehicle_id) references public.vehicles (id);

create index employees_current_vehicle_id_idx on public.employees (current_vehicle_id);

create table public.places (
  id         uuid primary key default gen_random_uuid(),
  name       text not null,
  address    text,
  lat        double precision,
  lng        double precision,
  kind       text not null default 'other',
  created_at timestamptz not null default now(),
  constraint places_name_not_blank check (btrim(name) <> ''),
  constraint places_kind_check check (kind in ('office', 'store', 'site', 'other')),
  constraint places_lat_lng_together check ((lat is null) = (lng is null)),
  constraint places_lat_check check (lat between -90 and 90),
  constraint places_lng_check check (lng between -180 and 180)
);

create unique index places_name_key on public.places (lower(name));

-- Populated places of Sri Lanka from GeoNames, used for "Near <town>".
-- id is the GeoNames geonameid. Rows are at the end of this file.
create table public.towns (
  id         bigint primary key,
  name       text not null,
  lat        double precision not null,
  lng        double precision not null,
  population integer not null default 0,
  constraint towns_lat_check check (lat between -90 and 90),
  constraint towns_lng_check check (lng between -180 and 180)
);

-- "Nearest town" is a small box search around a point.
create index towns_lat_lng_idx on public.towns (lat, lng);

-- Zoho Books projects (jobs). Filled by the connector tool import_projects.
create table public.projects (
  id              uuid primary key default gen_random_uuid(),
  zoho_project_id text not null,
  job_no          text,
  short_name      text,
  name            text not null,
  customer_id     text,
  customer_name   text,
  status          text,
  updated_at      timestamptz not null default now(),
  constraint projects_zoho_project_id_key unique (zoho_project_id)
);

-- Matching order (Allowance Desk doc, section 7.2): full name, then the part
-- after the first "_" (short_name), then the number before it (job_no).
create index projects_name_lower_idx on public.projects (lower(name));
create index projects_short_name_lower_idx on public.projects (lower(short_name));
create index projects_job_no_idx on public.projects (job_no);
create index projects_customer_id_idx on public.projects (customer_id);


-- -----------------------------------------------------------------------------
-- 2. Tasks, stops, project split, vehicle requests
-- -----------------------------------------------------------------------------

create table public.tasks (
  id                uuid primary key default gen_random_uuid(),
  title             text not null,
  label             text,
  employee_id       uuid not null references public.employees (id),
  vehicle_id        uuid not null references public.vehicles (id),
  start_at          timestamptz not null,
  end_by            timestamptz,
  passengers        integer,
  contact_name      text,
  contact_phone     text,
  notes             text,
  status            text not null default 'assigned',
  sent_at           timestamptz not null default now(),
  seen_at           timestamptz,
  started_at        timestamptz,
  completed_at      timestamptz,
  start_odometer_km integer,
  end_odometer_km   integer,
  km                integer generated always as (end_odometer_km - start_odometer_km) stored,
  request_id        uuid,
  created_by        text,
  cancelled_reason  text,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  constraint tasks_title_not_blank check (btrim(title) <> ''),
  constraint tasks_status_check check (status in ('assigned', 'in_progress', 'completed', 'cancelled')),
  constraint tasks_end_by_after_start check (end_by >= start_at),
  constraint tasks_passengers_check check (passengers >= 0),
  constraint tasks_start_odometer_check check (start_odometer_km >= 0),
  constraint tasks_end_needs_start_odometer check (end_odometer_km is null or start_odometer_km is not null),
  constraint tasks_km_not_negative check (end_odometer_km >= start_odometer_km),
  constraint tasks_started_fields check (
    status not in ('in_progress', 'completed')
    or (started_at is not null and start_odometer_km is not null)
  ),
  constraint tasks_completed_fields check (
    status <> 'completed'
    or (completed_at is not null and end_odometer_km is not null)
  ),
  constraint tasks_completed_after_started check (completed_at >= started_at),
  constraint tasks_cancelled_reason check (
    status <> 'cancelled' or btrim(coalesce(cancelled_reason, '')) <> ''
  )
);

create index tasks_employee_start_idx on public.tasks (employee_id, start_at);
create index tasks_vehicle_start_idx on public.tasks (vehicle_id, start_at);
create index tasks_start_at_idx on public.tasks (start_at);
create index tasks_open_status_idx on public.tasks (status) where status in ('assigned', 'in_progress');
create index tasks_request_id_idx on public.tasks (request_id) where request_id is not null;

-- A driver works on one task at a time.
create unique index tasks_one_in_progress_per_driver
  on public.tasks (employee_id) where status = 'in_progress';

create table public.task_stops (
  id         uuid primary key default gen_random_uuid(),
  task_id    uuid not null references public.tasks (id) on delete cascade,
  seq        integer not null,
  type       text not null,
  place_id   uuid references public.places (id),
  place_name text not null,
  address    text,
  lat        double precision,
  lng        double precision,
  status     text not null default 'pending',
  arrived_at timestamptz,
  done_at    timestamptz,
  constraint task_stops_task_seq_key unique (task_id, seq),
  constraint task_stops_seq_check check (seq >= 1),
  constraint task_stops_type_check check (type in ('pickup', 'drop', 'visit')),
  constraint task_stops_status_check check (status in ('pending', 'arrived', 'done', 'skipped')),
  constraint task_stops_place_name_not_blank check (btrim(place_name) <> ''),
  constraint task_stops_lat_lng_together check ((lat is null) = (lng is null)),
  constraint task_stops_lat_check check (lat between -90 and 90),
  constraint task_stops_lng_check check (lng between -180 and 180)
);

create index task_stops_place_id_idx on public.task_stops (place_id) where place_id is not null;

-- How a task's cost is split across Zoho projects. project_id null = Fame
-- internal. The percentages of a task total 100 (trigger in section 7).
create table public.task_projects (
  id         uuid primary key default gen_random_uuid(),
  task_id    uuid not null references public.tasks (id) on delete cascade,
  project_id uuid references public.projects (id),
  percent    numeric(5, 2) not null,
  constraint task_projects_task_project_key unique nulls not distinct (task_id, project_id),
  constraint task_projects_percent_check check (percent > 0 and percent <= 100)
);

create index task_projects_project_id_idx on public.task_projects (project_id);

create table public.vehicle_requests (
  id                       uuid primary key default gen_random_uuid(),
  requested_by_name        text not null,
  requested_by_employee_id uuid references public.employees (id),
  project_id               uuid references public.projects (id),
  project_label            text,
  needed_at                timestamptz not null,
  back_by                  timestamptz,
  route_from               text,
  route_to                 text,
  need_type                text,
  pax                      integer,
  tools                    boolean not null default false,
  note                     text,
  status                   text not null default 'waiting',
  decided_at               timestamptz,
  decided_by               text,
  decline_reason           text,
  task_id                  uuid references public.tasks (id),
  created_at               timestamptz not null default now(),
  constraint vehicle_requests_name_not_blank check (btrim(requested_by_name) <> ''),
  constraint vehicle_requests_need_type_check check (need_type in ('car', 'van', 'double_cab', 'lorry', 'other')),
  constraint vehicle_requests_pax_check check (pax >= 0),
  constraint vehicle_requests_back_after_needed check (back_by >= needed_at),
  constraint vehicle_requests_status_check check (status in ('waiting', 'approved', 'declined')),
  constraint vehicle_requests_decided_at_check check ((status = 'waiting') = (decided_at is null)),
  constraint vehicle_requests_decline_reason_check check (
    status <> 'declined' or btrim(coalesce(decline_reason, '')) <> ''
  )
);

create index vehicle_requests_status_needed_idx on public.vehicle_requests (status, needed_at);
create index vehicle_requests_task_id_idx on public.vehicle_requests (task_id) where task_id is not null;
create index vehicle_requests_project_id_idx on public.vehicle_requests (project_id) where project_id is not null;

alter table public.tasks
  add constraint tasks_request_id_fkey
  foreign key (request_id) references public.vehicle_requests (id);


-- -----------------------------------------------------------------------------
-- 3. Location sharing
-- -----------------------------------------------------------------------------

-- One row per "Sharing my location" on -> off period.
create table public.duty_sessions (
  id          uuid primary key default gen_random_uuid(),
  employee_id uuid not null references public.employees (id),
  vehicle_id  uuid references public.vehicles (id),
  started_at  timestamptz not null default now(),
  ended_at    timestamptz,
  end_reason  text,
  device_info jsonb,
  constraint duty_sessions_end_reason_check check (end_reason in ('driver', 'auto', 'admin')),
  constraint duty_sessions_end_fields_together check ((ended_at is null) = (end_reason is null)),
  constraint duty_sessions_ended_after_started check (ended_at >= started_at)
);

create unique index duty_sessions_one_open_per_employee
  on public.duty_sessions (employee_id) where ended_at is null;
create index duty_sessions_employee_started_idx on public.duty_sessions (employee_id, started_at desc);
create index duty_sessions_vehicle_id_idx on public.duty_sessions (vehicle_id) where vehicle_id is not null;

create table public.location_points (
  id          bigint generated always as identity primary key,
  employee_id uuid not null references public.employees (id),
  session_id  uuid not null references public.duty_sessions (id),
  recorded_at timestamptz not null,
  lat         double precision not null,
  lng         double precision not null,
  accuracy_m  real,
  speed_mps   real,
  heading     real,
  battery_pct smallint,
  is_mock     boolean not null default false,
  source      text not null default 'app',
  received_at timestamptz not null default now(),
  -- Also the retry key: the app uploads with "on conflict do nothing".
  constraint location_points_employee_recorded_key unique (employee_id, recorded_at),
  constraint location_points_lat_check check (lat between -90 and 90),
  constraint location_points_lng_check check (lng between -180 and 180),
  constraint location_points_source_check check (source in ('app'))
);

create index location_points_session_id_idx on public.location_points (session_id);

-- Latest known position per driver. Written only by triggers (section 7).
create table public.driver_latest (
  employee_id uuid primary key references public.employees (id),
  session_id  uuid references public.duty_sessions (id),
  lat         double precision,
  lng         double precision,
  accuracy_m  real,
  speed_mps   real,
  battery_pct smallint,
  recorded_at timestamptz,
  sharing     boolean not null default false
);


-- -----------------------------------------------------------------------------
-- 4. Photos, odometer, fuel, vehicle reports
-- -----------------------------------------------------------------------------

-- One row per file in the private bucket driver-photos.
-- storage_path = <employee_id>/<yyyy-mm-dd>/<uuid>.jpg
create table public.photos (
  id                uuid primary key default gen_random_uuid(),
  employee_id       uuid not null references public.employees (id),
  kind              text not null,
  storage_path      text not null,
  taken_at          timestamptz not null default now(),
  lat               double precision,
  lng               double precision,
  odometer_log_id   uuid,
  fuel_log_id       uuid,
  vehicle_report_id uuid,
  claim_line_id     uuid,
  constraint photos_storage_path_key unique (storage_path),
  constraint photos_kind_check check (kind in ('odometer', 'fuel_receipt', 'vehicle_report', 'bill')),
  constraint photos_path_in_own_folder check (starts_with(storage_path, employee_id::text || '/')),
  constraint photos_one_link check (
    num_nonnulls(odometer_log_id, fuel_log_id, vehicle_report_id, claim_line_id) <= 1
  ),
  constraint photos_lat_lng_together check ((lat is null) = (lng is null)),
  constraint photos_lat_check check (lat between -90 and 90),
  constraint photos_lng_check check (lng between -180 and 180)
);

create index photos_employee_taken_idx on public.photos (employee_id, taken_at desc);

create table public.odometer_logs (
  id          uuid primary key default gen_random_uuid(),
  vehicle_id  uuid not null references public.vehicles (id),
  employee_id uuid not null references public.employees (id),
  task_id     uuid references public.tasks (id),
  reading_km  integer not null,
  ocr_value   integer,
  photo_id    uuid references public.photos (id),
  kind        text not null default 'manual',
  logged_at   timestamptz not null default now(),
  constraint odometer_logs_reading_check check (reading_km >= 0),
  constraint odometer_logs_kind_check check (kind in ('task_start', 'task_end', 'manual')),
  constraint odometer_logs_task_kind_check check (kind = 'manual' or task_id is not null)
);

create index odometer_logs_vehicle_logged_idx on public.odometer_logs (vehicle_id, logged_at desc);
create index odometer_logs_employee_logged_idx on public.odometer_logs (employee_id, logged_at desc);
create index odometer_logs_task_id_idx on public.odometer_logs (task_id) where task_id is not null;
create index odometer_logs_photo_id_idx on public.odometer_logs (photo_id) where photo_id is not null;

create table public.fuel_logs (
  id               uuid primary key default gen_random_uuid(),
  vehicle_id       uuid not null references public.vehicles (id),
  employee_id      uuid not null references public.employees (id),
  task_id          uuid references public.tasks (id),
  litres           numeric(8, 2),
  amount_cents     bigint,
  receipt_photo_id uuid references public.photos (id),
  odometer_km      integer,
  logged_at        timestamptz not null default now(),
  constraint fuel_logs_litres_check check (litres > 0),
  constraint fuel_logs_amount_check check (amount_cents >= 0),
  constraint fuel_logs_litres_or_amount check (litres is not null or amount_cents is not null),
  constraint fuel_logs_odometer_check check (odometer_km >= 0)
);

create index fuel_logs_vehicle_logged_idx on public.fuel_logs (vehicle_id, logged_at desc);
create index fuel_logs_employee_logged_idx on public.fuel_logs (employee_id, logged_at desc);
create index fuel_logs_task_id_idx on public.fuel_logs (task_id) where task_id is not null;
create index fuel_logs_receipt_photo_id_idx on public.fuel_logs (receipt_photo_id) where receipt_photo_id is not null;

create table public.vehicle_reports (
  id          uuid primary key default gen_random_uuid(),
  vehicle_id  uuid not null references public.vehicles (id),
  employee_id uuid not null references public.employees (id),
  task_id     uuid references public.tasks (id),
  category    text not null,
  note        text,
  status      text not null default 'open',
  created_at  timestamptz not null default now(),
  closed_at   timestamptz,
  office_note text,
  constraint vehicle_reports_category_check check (
    category in ('breakdown', 'accident', 'tyre', 'warning_light', 'other')
  ),
  constraint vehicle_reports_status_check check (status in ('open', 'in_garage', 'closed')),
  constraint vehicle_reports_closed_at_check check ((status = 'closed') = (closed_at is not null))
);

create index vehicle_reports_employee_created_idx on public.vehicle_reports (employee_id, created_at desc);
create index vehicle_reports_vehicle_created_idx on public.vehicle_reports (vehicle_id, created_at desc);
create index vehicle_reports_open_status_idx on public.vehicle_reports (status) where status <> 'closed';
create index vehicle_reports_task_id_idx on public.vehicle_reports (task_id) where task_id is not null;


-- -----------------------------------------------------------------------------
-- 5. Allowance claims (Phase C). Tables only: RLS is on with no policies and no
--    privileges, so only the service role can touch them for now. The rules
--    follow docs/Allowance_Desk_How_It_Works.md.
-- -----------------------------------------------------------------------------

create table public.allowance_types (
  id                   uuid primary key default gen_random_uuid(),
  name                 text not null,
  default_amount_cents bigint not null default 0,
  bills_allowed        boolean not null default true,
  active               boolean not null default true,
  sort_order           integer not null default 0,
  created_at           timestamptz not null default now(),
  constraint allowance_types_name_not_blank check (btrim(name) <> ''),
  constraint allowance_types_default_amount_check check (default_amount_cents >= 0)
);

create unique index allowance_types_name_key on public.allowance_types (lower(name));

-- One claim per employee per day worked; extra "missed bill" claims for the
-- same day are marked is_supplement.
create table public.claims (
  id            uuid primary key default gen_random_uuid(),
  employee_id   uuid not null references public.employees (id),
  work_date     date not null,
  status        text not null default 'pending',
  is_supplement boolean not null default false,
  split_method  text,
  remarks       text,
  submitted_at  timestamptz not null default now(),
  decided_at    timestamptz,
  decided_by    text,
  reject_reason text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  constraint claims_status_check check (status in ('pending', 'approved', 'rejected', 'withdrawn')),
  constraint claims_split_method_check check (split_method in ('time', 'manual')),
  constraint claims_remarks_length check (char_length(remarks) <= 500),
  constraint claims_decided_at_check check (
    (status in ('approved', 'rejected')) = (decided_at is not null)
  ),
  constraint claims_reject_reason_check check (
    status <> 'rejected' or btrim(coalesce(reject_reason, '')) <> ''
  )
);

create unique index claims_one_per_employee_day
  on public.claims (employee_id, work_date)
  where not is_supplement and status in ('pending', 'approved');
create index claims_employee_date_idx on public.claims (employee_id, work_date desc);
create index claims_pending_idx on public.claims (submitted_at) where status = 'pending';

-- One line per allowance type claimed for the day.
create table public.claim_lines (
  id                uuid primary key default gen_random_uuid(),
  claim_id          uuid not null references public.claims (id) on delete cascade,
  allowance_type_id uuid not null references public.allowance_types (id),
  amount_cents      bigint not null,
  constraint claim_lines_claim_type_key unique (claim_id, allowance_type_id),
  constraint claim_lines_amount_check check (amount_cents > 0)
);

create index claim_lines_allowance_type_id_idx on public.claim_lines (allowance_type_id);

-- Project sites worked that day. hours and amount_cents are filled when the
-- approver splits the cost.
create table public.claim_sites (
  id           uuid primary key default gen_random_uuid(),
  claim_id     uuid not null references public.claims (id) on delete cascade,
  project_id   uuid not null references public.projects (id),
  hours        numeric(4, 2),
  amount_cents bigint,
  constraint claim_sites_claim_project_key unique (claim_id, project_id),
  constraint claim_sites_hours_check check (hours > 0 and hours <= 24),
  constraint claim_sites_amount_check check (amount_cents >= 0)
);

create index claim_sites_project_id_idx on public.claim_sites (project_id);

-- photos points back at whatever it documents.
alter table public.photos
  add constraint photos_odometer_log_id_fkey
    foreign key (odometer_log_id) references public.odometer_logs (id),
  add constraint photos_fuel_log_id_fkey
    foreign key (fuel_log_id) references public.fuel_logs (id),
  add constraint photos_vehicle_report_id_fkey
    foreign key (vehicle_report_id) references public.vehicle_reports (id),
  add constraint photos_claim_line_id_fkey
    foreign key (claim_line_id) references public.claim_lines (id);

create index photos_odometer_log_id_idx on public.photos (odometer_log_id) where odometer_log_id is not null;
create index photos_fuel_log_id_idx on public.photos (fuel_log_id) where fuel_log_id is not null;
create index photos_vehicle_report_id_idx on public.photos (vehicle_report_id) where vehicle_report_id is not null;
create index photos_claim_line_id_idx on public.photos (claim_line_id) where claim_line_id is not null;


-- -----------------------------------------------------------------------------
-- 6. Office audit log: one row per connector tool call
-- -----------------------------------------------------------------------------

create table public.office_audit (
  id             bigint generated always as identity primary key,
  at             timestamptz not null default now(),
  tool           text not null,
  args_summary   text,
  result_summary text
);

create index office_audit_at_idx on public.office_audit (at desc);
create index office_audit_tool_at_idx on public.office_audit (tool, at desc);


-- -----------------------------------------------------------------------------
-- 7. Functions and triggers
-- -----------------------------------------------------------------------------

-- The employee behind the signed-in user, or null. Deactivated employees get
-- null, which closes every policy below for them at once.
create function public.current_employee_id()
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select e.id
  from public.employees e
  where e.auth_user_id = (select auth.uid())
    and e.active
$$;

create function public.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

create trigger employees_set_updated_at before update on public.employees
  for each row execute function public.set_updated_at();
create trigger vehicles_set_updated_at before update on public.vehicles
  for each row execute function public.set_updated_at();
create trigger projects_set_updated_at before update on public.projects
  for each row execute function public.set_updated_at();
create trigger tasks_set_updated_at before update on public.tasks
  for each row execute function public.set_updated_at();
create trigger claims_set_updated_at before update on public.claims
  for each row execute function public.set_updated_at();

-- driver_latest, part 1: a new location point replaces the stored position
-- only when it is newer than the one already there.
create function public.location_points_set_latest()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- A phone with a wrong clock must not pin "latest" to a time in the future.
  if new.recorded_at > now() + interval '5 minutes' then
    return null;
  end if;

  insert into public.driver_latest as dl
    (employee_id, session_id, lat, lng, accuracy_m, speed_mps, battery_pct, recorded_at, sharing)
  values
    (new.employee_id, new.session_id, new.lat, new.lng, new.accuracy_m, new.speed_mps,
     new.battery_pct, new.recorded_at,
     exists (select 1 from public.duty_sessions s
             where s.employee_id = new.employee_id and s.ended_at is null))
  on conflict (employee_id) do update
    set session_id  = excluded.session_id,
        lat         = excluded.lat,
        lng         = excluded.lng,
        accuracy_m  = excluded.accuracy_m,
        speed_mps   = excluded.speed_mps,
        battery_pct = excluded.battery_pct,
        recorded_at = excluded.recorded_at
    where dl.recorded_at is null or excluded.recorded_at > dl.recorded_at;

  return null;
end;
$$;

create trigger location_points_set_latest after insert on public.location_points
  for each row execute function public.location_points_set_latest();

-- driver_latest, part 2: sharing is true exactly while the driver has an open
-- duty session.
create function public.duty_sessions_set_sharing()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_open_session uuid;
begin
  select s.id into v_open_session
  from public.duty_sessions s
  where s.employee_id = new.employee_id and s.ended_at is null;

  insert into public.driver_latest as dl (employee_id, session_id, sharing)
  values (new.employee_id, coalesce(v_open_session, new.id), v_open_session is not null)
  on conflict (employee_id) do update
    set sharing    = excluded.sharing,
        session_id = case when excluded.sharing then excluded.session_id else dl.session_id end;

  return null;
end;
$$;

create trigger duty_sessions_set_sharing after insert or update of ended_at on public.duty_sessions
  for each row execute function public.duty_sessions_set_sharing();

-- Every odometer log updates the vehicle's current odometer. The newest
-- reading by logged_at wins, so a log that was queued offline and arrives late
-- does not overwrite a more recent one. A log dated in the future (wrong phone
-- clock) does not count as "more recent" and so cannot block later readings.
create function public.odometer_logs_set_vehicle_odometer()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.vehicles v
  set current_odometer_km = new.reading_km
  where v.id = new.vehicle_id
    and not exists (
      select 1 from public.odometer_logs o
      where o.vehicle_id = new.vehicle_id
        and o.logged_at > new.logged_at
        and o.logged_at <= now()
    );

  return null;
end;
$$;

create trigger odometer_logs_set_vehicle_odometer after insert on public.odometer_logs
  for each row execute function public.odometer_logs_set_vehicle_odometer();

-- A log names its photo (photo_id / receipt_photo_id). These two triggers fill
-- the link in the other direction on photos, and refuse a photo that belongs to
-- someone else, is of the wrong kind, or is already used.
create function public.odometer_logs_link_photo()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.photos p
  set odometer_log_id = new.id
  where p.id = new.photo_id
    and p.employee_id = new.employee_id
    and p.kind = 'odometer'
    and num_nonnulls(p.odometer_log_id, p.fuel_log_id, p.vehicle_report_id, p.claim_line_id) = 0;

  if not found then
    raise exception 'Photo % is not an unused odometer photo of this employee', new.photo_id;
  end if;

  return null;
end;
$$;

create trigger odometer_logs_link_photo after insert on public.odometer_logs
  for each row when (new.photo_id is not null)
  execute function public.odometer_logs_link_photo();

create function public.fuel_logs_link_photo()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.photos p
  set fuel_log_id = new.id
  where p.id = new.receipt_photo_id
    and p.employee_id = new.employee_id
    and p.kind = 'fuel_receipt'
    and num_nonnulls(p.odometer_log_id, p.fuel_log_id, p.vehicle_report_id, p.claim_line_id) = 0;

  if not found then
    raise exception 'Photo % is not an unused fuel receipt photo of this employee', new.receipt_photo_id;
  end if;

  return null;
end;
$$;

create trigger fuel_logs_link_photo after insert on public.fuel_logs
  for each row when (new.receipt_photo_id is not null)
  execute function public.fuel_logs_link_photo();

-- The percentages of a task's projects total 100. A task may also have no
-- project rows at all (it then counts as Fame internal). Checked at commit, so
-- all rows of a task can be written in one request.
create function public.task_projects_check_total()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_task_ids uuid[];
  v_task_id  uuid;
  v_total    numeric;
begin
  if tg_op = 'INSERT' then
    v_task_ids := array[new.task_id];
  elsif tg_op = 'DELETE' then
    v_task_ids := array[old.task_id];
  else
    v_task_ids := array[old.task_id, new.task_id];
  end if;

  foreach v_task_id in array v_task_ids loop
    -- Serialise concurrent edits of the same task's split.
    perform 1 from public.tasks t where t.id = v_task_id for update;

    select sum(tp.percent) into v_total
    from public.task_projects tp
    where tp.task_id = v_task_id;

    if v_total is not null and v_total <> 100 then
      raise exception 'Project percentages for task % must total 100, not %', v_task_id, v_total
        using errcode = 'check_violation';
    end if;
  end loop;

  return null;
end;
$$;

create constraint trigger task_projects_total_100
  after insert or update or delete on public.task_projects
  deferrable initially deferred
  for each row execute function public.task_projects_check_total();

-- What a driver may change on their own task. Column privileges (section 8)
-- limit them to seen_at, started_at, completed_at, the two odometer fields and
-- status; this trigger limits the values:
--   assigned -> in_progress   needs the start odometer
--   in_progress -> completed  needs the end odometer
-- Drivers cannot cancel, reopen or edit a finished task.
create function public.tasks_driver_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  -- The office connector (service_role) and SQL run by an admin are not
  -- restricted here.
  if current_user <> 'authenticated' then
    return new;
  end if;

  -- seen_at is recorded once, the first time the task is shown, and never
  -- later than now.
  if old.seen_at is not null then
    new.seen_at := old.seen_at;
  elsif new.seen_at is not null then
    new.seen_at := least(new.seen_at, now());
  end if;

  if new.status = old.status then
    if (new.started_at, new.completed_at, new.start_odometer_km, new.end_odometer_km)
       is distinct from
       (old.started_at, old.completed_at, old.start_odometer_km, old.end_odometer_km) then
      raise exception 'Times and odometer readings are set only when starting or completing a task';
    end if;

  elsif old.status = 'assigned' and new.status = 'in_progress' then
    if new.start_odometer_km is null then
      raise exception 'Start odometer is required to start a task';
    end if;
    if new.completed_at is not null or new.end_odometer_km is not null then
      raise exception 'A task cannot be started and completed in one step';
    end if;
    -- The phone may send its own time (a start saved while offline); never
    -- later than now.
    new.started_at := least(coalesce(new.started_at, now()), now());

  elsif old.status = 'in_progress' and new.status = 'completed' then
    if (new.started_at, new.start_odometer_km)
       is distinct from (old.started_at, old.start_odometer_km) then
      raise exception 'Start time and start odometer cannot change when completing a task';
    end if;
    if new.end_odometer_km is null then
      raise exception 'End odometer is required to complete a task';
    end if;
    if new.end_odometer_km < new.start_odometer_km then
      raise exception 'End odometer (%) is lower than start odometer (%)',
        new.end_odometer_km, new.start_odometer_km;
    end if;
    -- Kept between the start time and now.
    new.completed_at := greatest(least(coalesce(new.completed_at, now()), now()), new.started_at);

  else
    raise exception 'Drivers cannot change a task from % to %', old.status, new.status;
  end if;

  return new;
end;
$$;

create trigger tasks_driver_guard before update on public.tasks
  for each row execute function public.tasks_driver_guard();


-- -----------------------------------------------------------------------------
-- 8. Row Level Security: privileges
--    RLS is on for every table. Privileges say which tables and columns a role
--    can touch at all; the policies in section 9 then say which rows.
-- -----------------------------------------------------------------------------

alter table public.employees        enable row level security;
alter table public.rental_companies enable row level security;
alter table public.vehicles         enable row level security;
alter table public.places           enable row level security;
alter table public.towns            enable row level security;
alter table public.projects         enable row level security;
alter table public.tasks            enable row level security;
alter table public.task_stops       enable row level security;
alter table public.task_projects    enable row level security;
alter table public.vehicle_requests enable row level security;
alter table public.duty_sessions    enable row level security;
alter table public.location_points  enable row level security;
alter table public.driver_latest    enable row level security;
alter table public.photos           enable row level security;
alter table public.odometer_logs    enable row level security;
alter table public.fuel_logs        enable row level security;
alter table public.vehicle_reports  enable row level security;
alter table public.allowance_types  enable row level security;
alter table public.claims           enable row level security;
alter table public.claim_lines      enable row level security;
alter table public.claim_sites      enable row level security;
alter table public.office_audit     enable row level security;

-- Start from nothing, then grant exactly what is needed.
revoke all on all tables in schema public from anon, authenticated, service_role;
revoke all on all sequences in schema public from anon, authenticated, service_role;

-- Office connector: read, insert, update. No delete, no truncate.
grant select, insert, update on all tables in schema public to service_role;

-- Tables created by later migrations start the same way: nothing for anon or
-- signed-in users until a migration grants it, no delete for the connector.
alter default privileges for role postgres in schema public
  revoke all on tables from anon, authenticated, service_role;
alter default privileges for role postgres in schema public
  grant select, insert, update on tables to service_role;
alter default privileges for role postgres in schema public
  revoke all on sequences from anon, authenticated;
alter default privileges for role postgres in schema public
  revoke all on functions from anon, authenticated;

-- Drivers: what they can read.
grant select on
  public.employees, public.places, public.towns, public.projects,
  public.tasks, public.task_stops, public.task_projects,
  public.duty_sessions, public.location_points,
  public.photos, public.odometer_logs, public.fuel_logs, public.vehicle_reports
  to authenticated;
-- Vehicles: these nine columns only. Rent, rental contract, regular driver,
-- service and document details stay with the office. Because the privilege is
-- per column, "select *" on vehicles fails for a driver: the app must always
-- name these columns.
grant select (id, reg_no, make_model, vehicle_type, seats, current_odometer_km,
              monthly_km_allowance, in_garage, active)
  on public.vehicles to authenticated;

-- Drivers: what they can add.
grant insert on
  public.duty_sessions, public.photos, public.odometer_logs, public.fuel_logs
  to authenticated;
-- received_at stays the server's time.
grant insert (employee_id, session_id, recorded_at, lat, lng, accuracy_m, speed_mps,
              heading, battery_pct, is_mock, source)
  on public.location_points to authenticated;
-- status, closed_at and office_note belong to the office.
grant insert (id, vehicle_id, employee_id, task_id, category, note, created_at)
  on public.vehicle_reports to authenticated;

-- Drivers: the only columns they can change.
grant update (current_vehicle_id, language) on public.employees to authenticated;
grant update (seen_at, started_at, completed_at, start_odometer_km, end_odometer_km, status)
  on public.tasks to authenticated;
grant update (status, arrived_at, done_at) on public.task_stops to authenticated;
grant update (ended_at, end_reason) on public.duty_sessions to authenticated;

-- Functions: nobody may call the trigger functions directly; signed-in users
-- and the connector may call current_employee_id(). Postgres lets everyone
-- execute a new function by default, so each function added by a later
-- migration needs the same "revoke all ... from public, anon, authenticated".
revoke all on function public.current_employee_id()                from public, anon, authenticated;
revoke all on function public.set_updated_at()                     from public, anon, authenticated;
revoke all on function public.location_points_set_latest()         from public, anon, authenticated;
revoke all on function public.duty_sessions_set_sharing()          from public, anon, authenticated;
revoke all on function public.odometer_logs_set_vehicle_odometer() from public, anon, authenticated;
revoke all on function public.odometer_logs_link_photo()           from public, anon, authenticated;
revoke all on function public.fuel_logs_link_photo()               from public, anon, authenticated;
revoke all on function public.task_projects_check_total()          from public, anon, authenticated;
revoke all on function public.tasks_driver_guard()                 from public, anon, authenticated;

grant execute on function public.current_employee_id() to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- 9. Row Level Security: policies
--    All policies are for role "authenticated" (a signed-in driver). There are
--    none for anon. Tables with no policy here cannot be reached by drivers at
--    all: rental_companies, vehicle_requests, driver_latest, office_audit,
--    allowance_types, claims, claim_lines, claim_sites.
--    "me" below means (select public.current_employee_id()).
-- -----------------------------------------------------------------------------

-- employees: a driver sees only their own row.
create policy employees_select_self on public.employees
  for select to authenticated
  using (id = (select public.current_employee_id()));

-- employees: a driver changes only their own row (columns: current_vehicle_id,
-- language), and the vehicle they pick must be an active one.
create policy employees_update_self on public.employees
  for update to authenticated
  using (id = (select public.current_employee_id()))
  with check (
    id = (select public.current_employee_id())
    and (
      current_vehicle_id is null
      or exists (
        select 1 from public.vehicles v
        where v.id = employees.current_vehicle_id and v.active
      )
    )
  );

-- vehicles: any active employee sees the active vehicles (only the nine
-- columns granted in section 8).
create policy vehicles_select_active on public.vehicles
  for select to authenticated
  using (active and (select public.current_employee_id()) is not null);

-- places, projects, towns: any active employee can read them.
create policy places_select_employees on public.places
  for select to authenticated
  using ((select public.current_employee_id()) is not null);

create policy projects_select_employees on public.projects
  for select to authenticated
  using ((select public.current_employee_id()) is not null);

create policy towns_select_employees on public.towns
  for select to authenticated
  using ((select public.current_employee_id()) is not null);

-- tasks: a driver sees only the tasks assigned to them.
create policy tasks_select_own on public.tasks
  for select to authenticated
  using (employee_id = (select public.current_employee_id()));

-- tasks: a driver updates only their own tasks (columns and allowed status
-- changes are limited by section 8 and tasks_driver_guard).
create policy tasks_update_own on public.tasks
  for update to authenticated
  using (employee_id = (select public.current_employee_id()))
  with check (employee_id = (select public.current_employee_id()));

-- task_stops: a driver sees the stops of their own tasks.
create policy task_stops_select_own on public.task_stops
  for select to authenticated
  using (
    exists (
      select 1 from public.tasks t
      where t.id = task_stops.task_id
        and t.employee_id = (select public.current_employee_id())
    )
  );

-- task_stops: a driver marks stops (status, arrived_at, done_at) only on their
-- own task and only while that task is in progress.
create policy task_stops_update_own_in_progress on public.task_stops
  for update to authenticated
  using (
    exists (
      select 1 from public.tasks t
      where t.id = task_stops.task_id
        and t.employee_id = (select public.current_employee_id())
        and t.status = 'in_progress'
    )
  )
  with check (
    exists (
      select 1 from public.tasks t
      where t.id = task_stops.task_id
        and t.employee_id = (select public.current_employee_id())
        and t.status = 'in_progress'
    )
  );

-- task_projects: a driver sees the project split of their own tasks.
create policy task_projects_select_own on public.task_projects
  for select to authenticated
  using (
    exists (
      select 1 from public.tasks t
      where t.id = task_projects.task_id
        and t.employee_id = (select public.current_employee_id())
    )
  );

-- duty_sessions: a driver sees their own sharing periods.
create policy duty_sessions_select_own on public.duty_sessions
  for select to authenticated
  using (employee_id = (select public.current_employee_id()));

-- duty_sessions: a driver starts a sharing period for themselves; 'admin' as
-- the end reason is reserved for the office.
create policy duty_sessions_insert_own on public.duty_sessions
  for insert to authenticated
  with check (
    employee_id = (select public.current_employee_id())
    and (end_reason is null or end_reason in ('driver', 'auto'))
  );

-- duty_sessions: a driver can end their own open sharing period, nothing else
-- (a closed period cannot be changed or reopened).
create policy duty_sessions_update_close_own on public.duty_sessions
  for update to authenticated
  using (employee_id = (select public.current_employee_id()) and ended_at is null)
  with check (
    employee_id = (select public.current_employee_id())
    and ended_at is not null
    and end_reason in ('driver', 'auto')
  );

-- location_points: a driver sees their own points.
create policy location_points_select_own on public.location_points
  for select to authenticated
  using (employee_id = (select public.current_employee_id()));

-- location_points: a driver uploads points for themselves, into one of their
-- own sharing periods.
create policy location_points_insert_own on public.location_points
  for insert to authenticated
  with check (
    employee_id = (select public.current_employee_id())
    and exists (
      select 1 from public.duty_sessions s
      where s.id = location_points.session_id
        and s.employee_id = (select public.current_employee_id())
    )
  );

-- photos: a driver sees their own photo records.
create policy photos_select_own on public.photos
  for select to authenticated
  using (employee_id = (select public.current_employee_id()));

-- photos: a driver adds photo records for themselves. A vehicle-report photo
-- must point at their own report; the odometer and fuel links are filled by
-- triggers; bill photos for claims wait for Phase C.
create policy photos_insert_own on public.photos
  for insert to authenticated
  with check (
    employee_id = (select public.current_employee_id())
    and odometer_log_id is null
    and fuel_log_id is null
    and claim_line_id is null
    and (
      vehicle_report_id is null
      or exists (
        select 1 from public.vehicle_reports r
        where r.id = photos.vehicle_report_id
          and r.employee_id = (select public.current_employee_id())
      )
    )
  );

-- odometer_logs: a driver sees and adds their own readings.
create policy odometer_logs_select_own on public.odometer_logs
  for select to authenticated
  using (employee_id = (select public.current_employee_id()));

create policy odometer_logs_insert_own on public.odometer_logs
  for insert to authenticated
  with check (employee_id = (select public.current_employee_id()));

-- fuel_logs: a driver sees and adds their own fuel entries.
create policy fuel_logs_select_own on public.fuel_logs
  for select to authenticated
  using (employee_id = (select public.current_employee_id()));

create policy fuel_logs_insert_own on public.fuel_logs
  for insert to authenticated
  with check (employee_id = (select public.current_employee_id()));

-- vehicle_reports: a driver sees and sends their own reports (always created
-- as 'open'; the office changes the status).
create policy vehicle_reports_select_own on public.vehicle_reports
  for select to authenticated
  using (employee_id = (select public.current_employee_id()));

create policy vehicle_reports_insert_own on public.vehicle_reports
  for insert to authenticated
  with check (employee_id = (select public.current_employee_id()));


-- -----------------------------------------------------------------------------
-- 10. Storage: private bucket "driver-photos"
--     Path: <employee_id>/<yyyy-mm-dd>/<uuid>.jpg. The office sees photos only
--     through signed URLs made by the connector.
-- -----------------------------------------------------------------------------

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('driver-photos', 'driver-photos', false, 5242880, array['image/jpeg'])
on conflict (id) do update
  set public             = false,
      file_size_limit    = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- A driver uploads only into their own <employee_id>/ folder.
create policy driver_photos_insert_own_folder on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'driver-photos'
    and (storage.foldername(name))[1] = (select public.current_employee_id())::text
  );

-- A driver reads only files in their own <employee_id>/ folder.
create policy driver_photos_select_own_folder on storage.objects
  for select to authenticated
  using (
    bucket_id = 'driver-photos'
    and (storage.foldername(name))[1] = (select public.current_employee_id())::text
  );


-- -----------------------------------------------------------------------------
-- 11. Realtime: the Today screen listens for new and changed tasks. Realtime
--     applies the same RLS, so a driver only receives their own rows.
-- -----------------------------------------------------------------------------

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    alter publication supabase_realtime add table public.tasks, public.task_stops;
  end if;
end;
$$;


